              rankingScores[i] += statValues[STAT_DEF];
              rankingScores[i] += statValues[STAT_SPATK];
              rankingScores[i] += statValues[STAT_SPDEF];
              rankingScores[i] += statValues[STAT_SPEED];
              rankingScores[i] += statValues[STAT_HP];
