/** static int SelectOpponentMonsFromParty(int *partyMovePoints, bool8 allowRandom) */
export function SelectOpponentMonsFromParty(partyMovePoints: any, allowRandom: any): any {
  let i, j;
      let selectedMonBits: any = 0;
      const partyPositions: any[] = [];

      for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
          partyPositions[i] = i;

       
      if (partyMovePoints[0] == partyMovePoints[1]
       && partyMovePoints[0] == partyMovePoints[2])
      {
          if (allowRandom)
          {
              i = 0;
              while (i != DOME_BATTLE_PARTY_SIZE)
              {
                  let rand: any = Random() & FRONTIER_PARTY_SIZE;
                  if (rand != FRONTIER_PARTY_SIZE && !(selectedMonBits & gBitTable[rand]))
                  {
                      selectedMonBits |= gBitTable[rand];
                      i++;
                  }
              }
          }
      }
      else
      {
          for (i = 0; i < DOME_BATTLE_PARTY_SIZE; i++)
          {
              for (j = i + 1; j < FRONTIER_PARTY_SIZE; j++)
              {
                  let temp: any = null;

                  if (partyMovePoints[i] < partyMovePoints[j])
                  {
                      SWAP(partyMovePoints[i], partyMovePoints[j],temp)
                      SWAP(partyPositions[i], partyPositions[j], temp)
                  }

                  if (partyMovePoints[i] == partyMovePoints[j] && (Random() & 1))
                  {
                      SWAP(partyMovePoints[i], partyMovePoints[j],temp)
                      SWAP(partyPositions[i], partyPositions[j], temp)
                  }
              }
          }

          for (i = 0; i < DOME_BATTLE_PARTY_SIZE; i++)
          {
              selectedMonBits |= gBitTable[partyPositions[i]];
          }
      }

      return selectedMonBits;
}

/** static int GetTypeEffectivenessPoints(int move, int targetSpecies, int mode) */
export function GetTypeEffectivenessPoints(move: any, targetSpecies: any, mode: any): any {
  let defType1, defType2, defAbility, moveType;
      let i: any = 0;
      let typePower: any = TYPE_x1;

      if (move == MOVE_NONE || move == MOVE_UNAVAILABLE || gBattleMoves[move].power == 0)
          return 0;

      defType1 = gSpeciesInfo[targetSpecies].types[0];
      defType2 = gSpeciesInfo[targetSpecies].types[1];
      defAbility = gSpeciesInfo[targetSpecies].abilities[0];
      moveType = gBattleMoves[move].type;

      if (defAbility == ABILITY_LEVITATE && moveType == TYPE_GROUND)
      {
           
           
          if (mode == EFFECTIVENESS_MODE_BAD)
          {
              typePower = 8;
              return typePower;
          }
      }
      else
      {
           
           
          while (TYPE_EFFECT_ATK_TYPE(i) != TYPE_ENDTABLE)
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == TYPE_FORESIGHT)
              {
                  i += 3;
                  continue;
              }
              if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                  if (TYPE_EFFECT_DEF_TYPE(i) == defType1)
                      if ((defAbility == ABILITY_WONDER_GUARD && TYPE_EFFECT_MULTIPLIER(i) == WONDER_GUARD_EFFECTIVENESS) || defAbility != ABILITY_WONDER_GUARD)
                          typePower = (typePower * TYPE_EFFECT_MULTIPLIER(i)) / 10;
                  if (TYPE_EFFECT_DEF_TYPE(i) == defType2 && defType1 != defType2)
                      if ((defAbility == ABILITY_WONDER_GUARD && TYPE_EFFECT_MULTIPLIER(i) == WONDER_GUARD_EFFECTIVENESS) || defAbility != ABILITY_WONDER_GUARD)
                          typePower = (typePower * TYPE_EFFECT_MULTIPLIER(i)) / 10;
              }
              i += 3;
          }
      }

      switch (mode)
      {
      case EFFECTIVENESS_MODE_GOOD:
           
          switch (typePower)
          {
          case TYPE_x0:
          case TYPE_x0_25:
          case TYPE_x0_50:
          default:
              typePower = 0;
              break;
          case TYPE_x1:
              typePower = 2;
              break;
          case TYPE_x2:
              typePower = 4;
              break;
          case TYPE_x4:
              typePower = 8;
              break;
          }
          break;
      case EFFECTIVENESS_MODE_BAD:
           
           
          switch (typePower)
          {
          case TYPE_x0:
              typePower = 8;
              break;
          case TYPE_x0_25:
              typePower = 4;
              break;
          case TYPE_x0_50:
              typePower = 2;
              break;
          default:
          case TYPE_x1:
              typePower = 0;
              break;
          case TYPE_x2:
              typePower = -2;
              break;
          case TYPE_x4:
              typePower = -4;
              break;
          }
          break;
      case EFFECTIVENESS_MODE_AI_VS_AI:
           
           
          switch (typePower)
          {
          case TYPE_x0:
              typePower = -16;
              break;
          case TYPE_x0_25:
              typePower = -8;
              break;
          case TYPE_x0_50:
          default:
              typePower = 0;
              break;
          case TYPE_x1:
              typePower = 4;
              break;
          case TYPE_x2:
              typePower = 12;
              break;
          case TYPE_x4:
              typePower = 20;
              break;
          }
          break;
      }

      return typePower;
}

/** static u8 GetDomeTrainerMonIvs(u16 trainerId) */
export function GetDomeTrainerMonIvs(trainerId: any): any {
  let fixedIv: any = null;

      if (trainerId <= FRONTIER_TRAINER_JILL)          
          fixedIv = 3;
      else if (trainerId <= FRONTIER_TRAINER_CHLOE)    
          fixedIv = 6;
      else if (trainerId <= FRONTIER_TRAINER_SOFIA)    
          fixedIv = 9;
      else if (trainerId <= FRONTIER_TRAINER_JAZLYN)   
          fixedIv = 12;
      else if (trainerId <= FRONTIER_TRAINER_ALISON)   
          fixedIv = 15;
      else if (trainerId <= FRONTIER_TRAINER_LAMAR)    
          fixedIv = 18;
      else if (trainerId <= FRONTIER_TRAINER_TESS)     
          fixedIv = 21;
      else                                             
          fixedIv = MAX_PER_STAT_IVS;

      return fixedIv;
}

/** static int TournamentIdOfOpponent(int roundId, int trainerId) */
export function TournamentIdOfOpponent(roundId: any, trainerId: any): any {
  let i, j, opponentMax;

       
      for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
      {
          if (DOME_TRAINERS[i].trainerId == trainerId)
              break;
      }

       
      if (roundId != DOME_ROUND1)
      {
          if (roundId == DOME_FINAL)
              opponentMax = sIdToOpponentId[i][roundId] + 8;
          else
              opponentMax = sIdToOpponentId[i][roundId] + 4;

           
          for (j = sIdToOpponentId[i][roundId]; j < opponentMax; j++)
          {
              if (sTourneyTreeTrainerOpponentIds[j] != i && !DOME_TRAINERS[sTourneyTreeTrainerOpponentIds[j]].isEliminated)
                  break;
          }

          if (j != opponentMax)
              return sTourneyTreeTrainerOpponentIds[j];
          else
              return 0xFF;  
      }
      else
      {
          if (!DOME_TRAINERS[sIdToOpponentId[i][roundId]].isEliminated)
              return sIdToOpponentId[i][roundId];
          else
              return 0xFF;  
      }
}

